9	namespace Guardrails.Core.Execution;
10	
11	/// <summary>
12	/// The M4 DAG scheduler. Kahn-style readiness (a task becomes ready when every
13	/// dependency is green) feeding an unbounded <see cref="Channel{T}"/> consumed by
14	/// <c>maxParallelism</c> workers. A task that ends <c>needs-human</c> (or otherwise
15	/// non-green) blocks its TRANSITIVE dependents immediately while independent branches
16	/// keep running — every completed task is durable progress in the journal, and one run
17	/// surfaces every needs-human halt instead of one per run.
18	/// </summary>
19	public sealed class Scheduler
20	{
21	    private readonly PlanDefinition _plan;
22	    private readonly ITaskExecutor _executor;
23	    private readonly ISchedulerJournal _journal;
24	    private readonly IWorktreeProvider? _worktreeProvider;
25	    private readonly IRunObserver _observer;
26	    private readonly int _maxParallelism;
27	    private readonly IReVerifier? _reVerifier;
28	
29	    private readonly object _gate = new();
30	
31	    // Serialize-merges lock (plan 08 §3): one integration-settle at a time so that
32	    // non-FF union re-verify and B1 rollback are atomic w.r.t. other settling workers.
33	    private readonly SemaphoreSlim _integrationLock = new(1, 1);
34	
35	    // First unexpected (non-cancellation) executor fault wins; surfaced after WhenAll so the
36	    // run terminates deterministically with a harness error instead of hanging (see WorkerLoopAsync).
37	    private Exception? _fault;
38	
39	    private readonly IAiMergeWorker? _aiMergeWorker;
40	
41	    public Scheduler(
42	        PlanDefinition plan,
43	        ITaskExecutor executor,
44	        ISchedulerJournal journal,
45	        IWorktreeProvider? worktreeProvider = null,
46	        IRunObserver? observer = null,
47	        int? maxParallelism = null,
48	        IReVerifier? reVerifier = null,
49	        IAiMergeWorker? aiMergeWorker = null)
50	    {
51	        _plan = plan;
52	        _executor = executor;
53	        _journal = journal;
54	        _worktreeProvider = worktreeProvider;
55	        _observer = observer ?? IRunObserver.Null;
56	        _reVerifier = reVerifier;
57	        _aiMergeWorker = aiMergeWorker;
58	
59	        int requested = Math.Max(1, maxParallelism ?? plan.Config.MaxParallelism);
60	
61	        // F7 HARD GUARD: worktree mode (parallelism > 1) requires a worktree provider for
62	        // per-task isolation. With no provider, parallel workers would share the single
63	        // workspace and race undetectably (the rejected shared-workspace corruption class).
64	        // CLAMP to 1 (serial shared-workspace, the pre-plan-08 model) rather than running
65	        // an unsafe parallel run — and tell the observer so the demotion is not silent.
66	        if (requested > 1 && _worktreeProvider is null)
67	        {
68	            _observer.ParallelismClampedNoProvider(requested);
69	            requested = 1;
70	        }
71	
72	        _maxParallelism = requested;
73	    }
