75	    /// <summary>
76	    /// Run the plan to quiescence: every task green, blocked, or needs-human — or the
77	    /// token cancelled (in-flight attempts are journaled back to pending by the
78	    /// executor; unstarted tasks are reported <see cref="TaskOutcome.Cancelled"/>).
79	    /// </summary>
80	    public async Task<RunReport> RunAsync(PlanDefinition plan, CancellationToken cancellationToken = default)
81	    {
82	        var graph = new DependencyGraph(plan.Tasks);
83	        if (graph.FindCycle() is { } cycle)
84	        {
85	            // Validation (GR2007) catches this before a run; this guard keeps the
86	            // scheduler safe when embedded directly.
87	            throw new InvalidOperationException($"Dependency cycle: {string.Join(" -> ", cycle)}");
88	        }
89	
90	        var byId = plan.Tasks.ToDictionary(t => t.Id, StringComparer.Ordinal);
91	        var settled = new Dictionary<string, TaskResult>(StringComparer.Ordinal);
92	        var pendingDeps = new Dictionary<string, int>(StringComparer.Ordinal);
93	        var channel = Channel.CreateUnbounded<TaskEnvelope>();
94	
95	        // Create the integration handle once for this run (worktree mode only).
96	        string runId = Guid.NewGuid().ToString("N")[..8];
97	        IntegrationHandle? integ;
98	        try
99	        {
100	            integ = _worktreeProvider?.CreateIntegration(
101	                planName: Path.GetFileName(plan.PlanDirectory),
102	                runId: runId,
103	                cancellationToken);
104	        }
105	        catch (Exception ex)
106	        {
107	            // Issue #150/#160 — CreateIntegration runs BEFORE the worker loop's fault capture, so a
108	            // setup fault (e.g. a plan folder with no usable name component → the #160 guard's clear
109	            // diagnostic, or git unavailable) would otherwise escape unhandled as a raw stack trace.
110	            // Surface it through the same honest-halt ABORTED report the CLI renders cleanly.
111	            return BuildReport(plan, settled, cancelled: cancellationToken.IsCancellationRequested)
112	                with { Abort = BuildAbort(ex) };
113	        }
114	
115	        // B1_1/F1 resume pre-pass: a task is already green if the JOURNAL says Succeeded OR it is
116	        // already integrated on the PLAN BRANCH (a Guardrails-Task: trailer reachable from the tip).
117	        // Git is the durable resume truth: a kill after the FF/merge commit but before the journal
118	        // write leaves the task on the plan branch with no journal record — the union below stops it
119	        // being re-run. Prune this run's stale segment refs first so they can't be mistaken for work.
120	        var planBranchSettled = new HashSet<string>(StringComparer.Ordinal);
121	        if (_worktreeProvider is { } wp && integ is { } activeInteg)
122	        {
123	            wp.PruneStaleRunBranches(runId, activeInteg);
124	            planBranchSettled.UnionWith(wp.ReconcileFromPlanBranch(activeInteg));
125	        }
126	
127	        // --- resume pre-pass: journaled successes + plan-branch trailers are green ----------
128	        var preSettledGreen = new HashSet<string>(StringComparer.Ordinal);
129	        foreach (TaskNode task in plan.Tasks)
130	        {
131	            if (_journal.StatusOf(task.Id) == JournalTaskStatus.Succeeded
132	                || planBranchSettled.Contains(task.Id))
133	            {
134	                preSettledGreen.Add(task.Id);
135	                var skipped = new TaskResult
136	                {
137	                    TaskId = task.Id,
138	                    Outcome = TaskOutcome.Skipped,
139	                    Summary = "already succeeded (resumed) — skipped"
140	                };
141	                settled[task.Id] = skipped;
142	                _observer.TaskFinished(skipped);
143	            }
144	        }
145	
146	        int remaining = 0;
147	        foreach (TaskNode task in plan.Tasks)
148	        {
149	            if (preSettledGreen.Contains(task.Id))
150	            {
151	                continue;
152	            }
153	
154	            remaining++;
155	            pendingDeps[task.Id] = task.DependsOn.Count(d => !preSettledGreen.Contains(d));
156	        }
157	
158	        if (remaining == 0)
159	        {
160	            return BuildReport(plan, settled, cancelled: false);
161	        }
162	
163	        // Pre-create worktree handles only for initially-ready tasks (no pending deps).
164	        // Dependent tasks get their handles created LAZILY in OnSettledAsync AFTER the upstream
165	        // integration commits advance the plan branch — this is what makes FF possible for
166	        // linear chains: task B's segment is forked from task A's integrated HEAD, not from the
167	        // original plan-branch HEAD before A ran.
168	        var handles = new Dictionary<string, WorktreeHandle>(StringComparer.Ordinal);
169	        // DirectoryOwner (plan 08 topology-wiring M0): worktree path → current owning task id.
170	        // The single source of truth for "is this directory free to Discard / reuse?". Populated
171	        // on every CreateSegment/ForkFromTip; ownership transfers on ReuseSegment (M1). In M0 every
172	        // task still owns its own fresh directory, so this map mirrors the fresh-per-task baseline.
173	        var directoryOwner = new Dictionary<string, string>(StringComparer.Ordinal);
174	        foreach (TaskNode task in plan.Tasks)
175	        {
176	            if (!preSettledGreen.Contains(task.Id) && pendingDeps[task.Id] == 0)
177	            {
178	                WorktreeHandle handle = _worktreeProvider != null && integ != null
179	                    ? _worktreeProvider.CreateSegment(task.Id, attempt: 1, integ, cancellationToken)
180	                    : new WorktreeHandle();
181	                handles[task.Id] = handle;
182	                if (!string.IsNullOrEmpty(handle.WorktreePath))
183	                {
184	                    directoryOwner[handle.WorktreePath] = task.Id;
185	                }
186	            }
187	        }
188	
189	        foreach (TaskNode task in plan.Tasks)
190	        {
191	            if (!preSettledGreen.Contains(task.Id) && pendingDeps[task.Id] == 0)
192	            {
193	                channel.Writer.TryWrite(new TaskEnvelope(task, handles[task.Id]));
194	            }
195	        }
196	
197	        // --- workers ---------------------------------------------------------------------
198	        using var runCts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
199	        var context = new RunContext(graph, byId, settled, pendingDeps, channel, remaining, handles, directoryOwner, integ);
200	        int workerCount = Math.Min(_maxParallelism, remaining);
201	        Task[] workers = Enumerable.Range(0, workerCount)
202	            .Select(_ => Task.Run(() => WorkerLoopAsync(context, runCts), CancellationToken.None))
203	            .ToArray();
204	
205	        await Task.WhenAll(workers).ConfigureAwait(false);
206	
207	        // Issue #150 — honest halt instead of an unhandled crash. An unexpected infrastructure fault
208	        // (a task executor or integration step threw — e.g. an offline GitGuardian pre-commit hook
209	        // failing an INTERNAL commit, or git being unavailable) used to RE-THROW here, escaping
210	        // unhandled to the CLI as a raw stack-trace headline. Instead, build an ABORTED report that
211	        // carries the fault reason, still run the end-of-run cleanup sweep below, and let the CLI
212	        // render a one-line diagnostic + remedy (full detail to the logs) and exit non-zero.
213	        if (_fault is { } fault)
214	        {
215	            var abortReport = BuildReport(plan, settled, cancelled: cancellationToken.IsCancellationRequested)
216	                with { Abort = BuildAbort(fault) };
217	
218	            // Clean up this run's still-live worktrees exactly as the success path does, so an aborted
219	            // run does not orphan more than the next run's prune pre-pass already reclaims (the
220	            // intentional "fix, don't restart" retention of non-green segments still holds).
221	            if (!cancellationToken.IsCancellationRequested)
222	            {
223	                EndOfRunSweep(context, integ);
224	            }
225	
226	            return abortReport;
227	        }
228	
229	        RunReport report = BuildReport(plan, settled, cancelled: cancellationToken.IsCancellationRequested);
230	
231	        // --- C1 terminal whole-repo integration gate (§3.3/§4a) --------------------------
232	        // After every task settles green, re-run the run's integration-guardrail set on the
233	        // FINAL plan-branch HEAD (via the integration worktree) — the union's whole-repo
234	        // soundness boundary that backstops the per-hop FF-integrations a linear chain skipped.
235	        // A failing gate flips the run off-green (the sink task, or first task, to needs-human)
236	        // so mergeOnSuccess is refused and the report is not certified.
237	        //
238	        // preflights-impl deliverable 4: REPLACED by the terminal PlanGuardrailPhase (Guardrails.Cli,
239	        // SSOT §3.3/§7.1) for any plan that declares a plan-level <plan>/guardrails/ folder — that
240	        // phase runs AFTER this method returns, against the SAME merged HEAD, via the same IReVerifier
241	        // seam. This legacy per-task integrationGate/scope:"integration" sink-task run is SUPERSEDED
242	        // (never both) whenever plan.PlanGuardrails is non-empty; it stays live, unchanged, only for a
243	        // plan still on the retired sink-task modelling.
244	        if (report.AllSucceeded && _reVerifier != null && integ != null && plan.PlanGuardrails.Count == 0)
245	        {
246	            IReadOnlyList<GuardrailDefinition> integrationSet =
247	                GuardrailScopeFilter.IntegrationSet(plan.Tasks.SelectMany(t => t.Guardrails));
248	
249	            if (integrationSet.Count > 0)
250	            {
251	                ReVerifyResult gate = await _reVerifier
252	                    .ReVerifyAsync(integ.IntegrationWorktreePath, integrationSet, cancellationToken)
253	                    .ConfigureAwait(false);
254	
255	                if (!gate.Passed)
256	                {
257	                    report = WithTerminalGateFailure(plan, report, gate);
258	                }
259	            }
260	        }
261	
262	        // Deliver the completed plan branch to the user's branch when every task succeeded
263	        // and mergeOnSuccess is enabled. AI-merge is withheld: a conflict halts to needs-human
264	        // with the plan branch intact (SSOT §5.3).
265	        MergeOnSuccessResult? mergeOutcome = null;
266	        string? mergeDetail = null;
267	        if (report.AllSucceeded && plan.Config.MergeOnSuccess && _worktreeProvider != null && integ != null)
268	        {
269	            mergeOutcome = _worktreeProvider.MergePlanBranchIntoUserBranch(integ, cancellationToken);
270	            // Issue #150: when the user's git hook rejected the user-facing merge, surface the hook's
271	            // stderr so the CLI can show the actual reason (and a remedy) instead of a bare outcome.
272	            if (mergeOutcome == MergeOnSuccessResult.HookRejected)
273	            {
274	                mergeDetail = _worktreeProvider.LastMergeOnSuccessDetail;
275	            }
276	        }
277	
278	        // --- M2 end-of-run cleanup sweep (closes #126) -----------------------------------
279	        // After delivery, Discard every still-live segment/fork worktree directory this run created
280	        // (whatever remains owned in DirectoryOwner — the failure path already removed any it freed),
281	        // then PruneOrphans to clear the registrations. The integration worktree is reattached to the
282	        // plan branch and is NEVER in DirectoryOwner, so the sweep never touches it (design §D / 08 §7).
283	        //
284	        // Skipped on cancellation: a cancelled run journals in-flight tasks back to pending for
285	        // resume, and Discarding here would race the executor's in-flight teardown (design §C). The
286	        // next run's PruneStaleRunBranches pre-pass reclaims those directories.
287	        if (!cancellationToken.IsCancellationRequested)
288	        {
289	            EndOfRunSweep(context, integ);
290	        }
291	
292	        return report with { MergeOnSuccessOutcome = mergeOutcome, MergeOnSuccessDetail = mergeDetail };
293	    }
