295	    /// <summary>
296	    /// Build the <see cref="RunAbort"/> for an infrastructure fault (issue #150): a one-line headline
297	    /// + remedy for the console, and the full exception text for the run logs. A dev tool keeps the
298	    /// detail — just not as the headline.
299	    /// </summary>
300	    private static RunAbort BuildAbort(Exception fault) => new()
301	    {
302	        Headline = $"The run was aborted by an unexpected infrastructure fault: {fault.Message}",
303	        Remedy = "See the full exception in the run logs below. This is a harness/environment fault "
304	               + "(e.g. an offline or failing git hook on an internal commit, or git unavailable), "
305	               + "not a task failure — resolve it and re-run to resume.",
306	        Detail = fault.ToString()
307	    };
308	
309	    /// <summary>
310	    /// plan 08 topology-wiring M2 §D (#126): remove every segment/fork worktree directory owned by a
311	    /// task that settled GREEN, then prune stale registrations. A green task's work is durable on the
312	    /// plan branch, so its directory is pure waste — this is the direct #126 fix (a wholly-green run
313	    /// leaves no segment worktree behind).
314	    ///
315	    /// A NON-green task (needs-human / failed / blocked) keeps its directory: the "fix, don't restart"
316	    /// invariant (§3.2, open-risk #4) requires a failed attempt's worktree to survive so a human — or
317	    /// a resume's reset-and-retry — can inspect the scoped-revert artifacts and WIP. The next run's
318	    /// PruneStaleRunBranches pre-pass reclaims those. The <c>_integration</c> worktree is never in
319	    /// <see cref="RunContext.DirectoryOwner"/> and is therefore never swept.
320	    ///
321	    /// Best-effort — a cleanup failure logs (via <see cref="IRunObserver.CleanupFailed"/>) and
322	    /// continues; it must NEVER flip an otherwise-green run off-green (GitWorktreeProvider.Discard
323	    /// throws on a non-zero git exit, so each call-site swallows).
324	    /// </summary>
325	    private void EndOfRunSweep(RunContext context, IntegrationHandle? integ)
326	    {
327	        if (_worktreeProvider is not { } provider || integ is null)
328	        {
329	            return;
330	        }
331	
332	        // Snapshot under the gate (no workers are running now, but keep the discipline consistent).
333	        // Sweep only GREEN-owned directories; non-green tasks keep their worktree for fix/resume.
334	        List<KeyValuePair<string, string>> sweepable;
335	        lock (_gate)
336	        {
337	            sweepable = context.DirectoryOwner
338	                .Where(kv => context.Settled.TryGetValue(kv.Value, out TaskResult? r) && r.IsGreen)
339	                .ToList();
340	        }
341	
342	        foreach ((string path, string owner) in sweepable)
343	        {
344	            try
345	            {
346	                provider.Discard(new WorktreeHandle { WorktreePath = path });
347	            }
348	            catch (Exception ex)
349	            {
350	                _observer.CleanupFailed(owner, ex);
351	            }
352	            finally
353	            {
354	                lock (_gate)
355	                {
356	                    context.DirectoryOwner.Remove(path);
357	                }
358	            }
359	        }
360	
361	        try
362	        {
363	            provider.PruneOrphans(Array.Empty<string>(), integ);
364	        }
365	        catch (Exception ex)
366	        {
367	            _observer.CleanupFailed("(prune-orphans)", ex);
368	        }
369	    }
