371	    private async Task WorkerLoopAsync(RunContext context, CancellationTokenSource runCts)
372	    {
373	        CancellationToken cancellationToken = runCts.Token;
374	        try
375	        {
376	            await foreach (TaskEnvelope envelope in context.Channel.Reader.ReadAllAsync(cancellationToken).ConfigureAwait(false))
377	            {
378	                TaskNode task = envelope.Task;
379	                WorktreeHandle handle = MaterializeForkIfDeferred(context, envelope);
380	
381	                if (CostCapHaltFor(task) is { } capped)
382	                {
383	                    await OnSettledAsync(context, task, capped, handle, cancellationToken).ConfigureAwait(false);
384	                    continue;
385	                }
386	
387	                TaskResult result = await _executor.ExecuteAsync(task, handle, cancellationToken).ConfigureAwait(false);
388	
389	                await OnSettledAsync(context, task, result, handle, cancellationToken).ConfigureAwait(false);
390	            }
391	        }
392	        catch (OperationCanceledException)
393	        {
394	            // Cancelled drain.
395	        }
396	        catch (Exception ex)
397	        {
398	            lock (_gate)
399	            {
400	                _fault ??= ex;
401	            }
402	
403	            context.Channel.Writer.TryComplete();
404	            runCts.Cancel();
405	        }
406	    }
