408	    /// <summary>
409	    /// plan 08 topology-wiring M1 §B: materialize a deferred fork-the-rest sibling's worktree at
410	    /// dequeue — the actual <c>git worktree add</c> runs HERE, OFF the <see cref="_gate"/> every
411	    /// settling worker contends for. The fork roots off the producer's RECORDED sha (captured in
412	    /// the request under <c>_gate</c> at assignment, W-2), never a live rev-parse of the segment
413	    /// branch the inheritor may have advanced. Returns the envelope's existing handle unchanged
414	    /// when there is no deferred fork.
415	    /// </summary>
416	    private WorktreeHandle MaterializeForkIfDeferred(RunContext context, TaskEnvelope envelope)
417	    {
418	        if (envelope.Fork is not { } fork || _worktreeProvider is not { } provider)
419	        {
420	            return envelope.Handle;
421	        }
422	
423	        // git I/O off the gate.
424	        WorktreeHandle handle = provider.ForkFromTip(fork.ProducerRecordedSha, envelope.Task.Id, attempt: 1);
425	
426	        // Bookkeeping under the gate: record the assigned handle + directory ownership.
427	        lock (_gate)
428	        {
429	            context.Handles[envelope.Task.Id] = handle;
430	            if (!string.IsNullOrEmpty(handle.WorktreePath))
431	            {
432	                context.DirectoryOwner[handle.WorktreePath] = envelope.Task.Id;
433	            }
434	        }
435	
436	        return handle;
437	    }
