439	    private TaskResult? CostCapHaltFor(TaskNode task)
440	    {
441	        if (_plan.Config.MaxCostUsd is not { } cap || _journal.CurrentCostUsd() < cap)
442	        {
443	            return null;
444	        }
445	
446	        return new TaskResult
447	        {
448	            TaskId = task.Id,
449	            Outcome = TaskOutcome.NeedsHuman,
450	            Summary = $"cost cap reached: cumulative journaled cost has reached the configured " +
451	                      $"maxCostUsd (${cap}); task not launched."
452	        };
453	    }
