455	    /// <summary>
456	    /// Called after a task finishes (executor or cost-cap halt). For worktree-mode green results,
457	    /// performs the B1 deferred settle (fragment merge → git integration commit → journal settle)
458	    /// under <see cref="_integrationLock"/> BEFORE updating the shared run context under
459	    /// <see cref="_gate"/>. This ordering ensures dependents only become ready after the upstream
460	    /// integration has advanced the plan branch, making lazy handle creation FF-compatible.
461	    /// </summary>
462	    private async Task OnSettledAsync(
463	        RunContext context, TaskNode task, TaskResult result, WorktreeHandle handle, CancellationToken ct)
464	    {
465	        // B1 deferred settle (worktree mode, real segment): ValidateFragmentForSettle sets
466	        // DeferredSettle=true, meaning the Scheduler owns the fragment merge → git commit →
467	        // journal settle sequence under the integration lock.
468	        //
469	        // Old path (serial mode or fake provider): the executor already merged + journaled;
470	        // just call provider.Integrate directly so IWorktreeProvider.IntegrateCallCount tests pass.
471	        if (result.IsGreen && _worktreeProvider is { } provider && context.Integ is { } integ)
472	        {
473	            if (result.DeferredSettle)
474	            {
475	                await _integrationLock.WaitAsync(ct).ConfigureAwait(false);
476	                try
477	                {
478	                    result = await SettleAsync(task, result, handle, provider, integ, ct).ConfigureAwait(false);
479	                }
480	                finally
481	                {
482	                    _integrationLock.Release();
483	                }
484	            }
485	            else if (!string.IsNullOrEmpty(handle.WorktreePath))
486	            {
487	                // Non-deferred: executor already handled journal; just integrate the segment.
488	                provider.Integrate(handle, integ, CancellationToken.None);
489	            }
490	
491	            // #195 retry-salvage pruning (deliverable 6): once a task's FINAL settle (after the
492	            // deferred B1 settle above, which can still turn a green-looking result into NeedsHuman on
493	            // a failed union re-verify) is truly Succeeded, its salvage refs — its own prior
494	            // rolled-back partial attempts — have served their purpose and are pruned so they never
495	            // accumulate across a long-lived repo. Checked on result.Outcome (the POST-settle value),
496	            // never result.IsGreen (which is true before SettleAsync can still flip it to NeedsHuman).
497	            if (result.Outcome == TaskOutcome.Succeeded)
498	            {
499	                try { provider.PruneSalvageRefs(task.Id); }
500	                catch (Exception ex) { _observer.CleanupFailed(task.Id, ex); }
501	            }
502	        }
503	
504	        var newlyReady = new List<TaskEnvelope>();
505	        var newlyBlocked = new List<TaskResult>();
506	
507	        lock (_gate)
508	        {
509	            context.Settled[task.Id] = result;
510	            context.Remaining--;
511	
512	            if (result.IsGreen)
513	            {
514	                // Which dependents of this producer just had their LAST pending dep cleared?
515	                // (A multi-producer dependent here is a fan-in: it has other, already-green
516	                // producers, and reaches the merged plan tip — never reused, M1 §A1.)
517	                var justReady = new List<string>();
518	                foreach (string dependent in context.Graph.DependentsOf(task.Id))
519	                {
520	                    if (!context.Settled.ContainsKey(dependent) && --context.PendingDeps[dependent] == 0)
521	                    {
522	                        justReady.Add(dependent);
523	                    }
524	                }
525	
526	                AssignDependentHandles(context, task, justReady, newlyReady);
527	            }
528	            else if (result.Outcome != TaskOutcome.Cancelled)
529	            {
530	                foreach (string dependent in context.Graph.TransitiveDependentsOf(task.Id)
531	                             .OrderBy(d => d, StringComparer.Ordinal))
532	                {
533	                    if (context.Settled.ContainsKey(dependent))
534	                    {
535	                        continue;
536	                    }
537	
538	                    var blocked = new TaskResult
539	                    {
540	                        TaskId = dependent,
541	                        Outcome = TaskOutcome.Blocked,
542	                        Summary = $"blocked: dependency '{task.Id}' did not succeed"
543	                    };
544	                    context.Settled[dependent] = blocked;
545	                    context.Remaining--;
546	                    _journal.MarkBlocked(dependent);
547	                    newlyBlocked.Add(blocked);
548	                }
549	
550	                // M2 §C / open-risk #4: a permanently-failed (needs-human/failed) task's segment is
551	                // NOT Discarded mid-run. The "fix, don't restart" invariant (§3.2) keeps a failed
552	                // attempt's worktree alive so a human (or a retry) can inspect the scoped-revert
553	                // artifacts and WIP. Its directory stays owned in DirectoryOwner and is reclaimed by
554	                // the end-of-run sweep at quiescence — which is what closes #126 (design §D point 2:
555	                // "#126 is closed by the run-end sweep alone"). Cancellation skips the sweep, so a
556	                // cancelled task's worktree survives for the resume prune (T-11).
557	            }
558	
559	            if (context.Remaining == 0)
560	            {
561	                context.Channel.Writer.TryComplete();
562	            }
563	        }
564	
565	        _observer.TaskFinished(result);
566	        foreach (TaskResult blocked in newlyBlocked)
567	        {
568	            _observer.TaskFinished(blocked);
569	        }
570	
571	        // Each envelope already carries its assigned handle (fresh segment / reused directory) OR a
572	        // deferred fork request the worker materializes off-gate at dequeue (M1 §B).
573	        foreach (TaskEnvelope ready in newlyReady)
574	        {
575	            context.Channel.Writer.TryWrite(ready);
576	        }
577	    }
