579	    /// <summary>
580	    /// plan 08 topology-wiring M1 §A/§B: assign worktree handles to the dependents of a just-settled
581	    /// green producer <paramref name="producer"/>, choosing reuse vs fork vs fresh-segment.
582	    /// <list type="bullet">
583	    ///   <item><b>Multi-producer dependents (fan-in)</b> get a fresh <see cref="IWorktreeProvider.CreateSegment"/>
584	    ///     off the plan-branch tip, which already contains every producer's integrated work — never
585	    ///     reused (§A1).</item>
586	    ///   <item><b>Single-producer dependents</b> are the inherit-one/fork-rest fan-out. The inheritor
587	    ///     (longest downstream chain via <see cref="DependencyGraph.TransitiveDependentsOf"/>, ordinal-id
588	    ///     tiebreak) reuses the producer's segment directory via the pure-handle
589	    ///     <see cref="IWorktreeProvider.ReuseSegment"/> (safe under <see cref="_gate"/>; ownership
590	    ///     transfers to the inheritor). The rest fork off the producer's RECORDED sha — a DEFERRED
591	    ///     request the worker materializes off-gate (§B, W-2).</item>
592	    /// </list>
593	    /// Runs under <see cref="_gate"/>. All assignment + bookkeeping is here; only the fork's
594	    /// <c>git worktree add</c> is deferred off-gate.
595	    /// </summary>
596	    private void AssignDependentHandles(
597	        RunContext context, TaskNode producer, List<string> justReady, List<TaskEnvelope> newlyReady)
598	    {
599	        // Fan-in (multi-producer) dependents reach the merged plan tip with a fresh segment.
600	        var singleProducer = new List<string>();
601	        foreach (string dependent in justReady)
602	        {
603	            if (context.ById[dependent].DependsOn.Count > 1)
604	            {
605	                WorktreeHandle fanInHandle = CreateFreshSegment(context, dependent);
606	                context.Handles[dependent] = fanInHandle;
607	                RecordOwnership(context, fanInHandle, dependent);
608	                newlyReady.Add(new TaskEnvelope(context.ById[dependent], fanInHandle));
609	            }
610	            else
611	            {
612	                singleProducer.Add(dependent);
613	            }
614	        }
615	
616	        if (singleProducer.Count == 0)
617	        {
618	            return;
619	        }
620	
621	        // Inherit-one: the single-producer dependent with the longest downstream chain reuses the
622	        // producer's directory; ordinal-id tiebreak. The producer's handle carries the RecordedSha
623	        // that Integrate captured during this settle (strict happens-before).
624	        string inheritor = singleProducer
625	            .OrderByDescending(d => context.Graph.TransitiveDependentsOf(d).Count)
626	            .ThenBy(d => d, StringComparer.Ordinal)
627	            .First();
628	
629	        WorktreeHandle? producerHandle =
630	            _worktreeProvider != null ? context.Handles.GetValueOrDefault(producer.Id) : null;
631	
632	        foreach (string dependent in singleProducer)
633	        {
634	            if (dependent == inheritor && _worktreeProvider is { } reuseProvider && producerHandle is { } ph)
635	            {
636	                // Pure handle rewrite — no git, safe under _gate. Ownership of the producer's
637	                // directory transfers to the inheritor.
638	                WorktreeHandle reused = reuseProvider.ReuseSegment(ph, dependent, attempt: 1);
639	                context.Handles[dependent] = reused;
640	                if (!string.IsNullOrEmpty(reused.WorktreePath))
641	                {
642	                    context.DirectoryOwner[reused.WorktreePath] = dependent;
643	                }
644	                newlyReady.Add(new TaskEnvelope(context.ById[dependent], reused));
645	            }
646	            else if (_worktreeProvider is not null && producerHandle is { } pf)
647	            {
648	                // Fork-the-rest: defer the git worktree add to the worker (off-gate). Root off the
649	                // producer's RECORDED sha — never the live segment-branch tip the inheritor advances.
650	                var fork = new ForkRequest(pf.RecordedCommitSha);
651	                newlyReady.Add(new TaskEnvelope(context.ById[dependent], new WorktreeHandle(), fork));
652	            }
653	            else
654	            {
655	                // No provider (serial/fake-less mode): an empty placeholder handle, as before.
656	                var placeholder = new WorktreeHandle();
657	                context.Handles[dependent] = placeholder;
658	                newlyReady.Add(new TaskEnvelope(context.ById[dependent], placeholder));
659	            }
660	        }
661	    }
662	
663	    /// <summary>Create a fresh segment off the plan-branch tip (or an empty handle without a provider).</summary>
664	    private WorktreeHandle CreateFreshSegment(RunContext context, string taskId) =>
665	        _worktreeProvider != null && context.Integ != null
666	            ? _worktreeProvider.CreateSegment(taskId, attempt: 1, context.Integ, CancellationToken.None)
667	            : new WorktreeHandle();
668	
669	    /// <summary>Record directory ownership for a non-empty handle path (M0 bookkeeping; under <see cref="_gate"/>).</summary>
670	    private static void RecordOwnership(RunContext context, WorktreeHandle handle, string taskId)
671	    {
672	        if (!string.IsNullOrEmpty(handle.WorktreePath))
673	        {
674	            context.DirectoryOwner[handle.WorktreePath] = taskId;
675	        }
676	    }
677	
678	    /// <summary>
679	    /// B1 fixed-order settle under <see cref="_integrationLock"/>:
680	    /// (1) deep-merge fragment into state.json,
681	    /// (2) git integration commit (FF or non-FF merge),
682	    /// (3) reserve mergeSequence + journal RecordSettle.
683	    /// On non-FF failure: restore state.json, reset integration worktree, journal NeedsHuman.
684	    /// </summary>
685	    private async Task<TaskResult> SettleAsync(
686	        TaskNode task,
687	        TaskResult result,
688	        WorktreeHandle handle,
689	        IWorktreeProvider provider,
690	        IntegrationHandle integ,
691	        CancellationToken ct)
692	    {
693	        string statePath = Path.Combine(_plan.PlanDirectory, "state", "state.json");
694	        string preMergeState = File.Exists(statePath) ? File.ReadAllText(statePath) : "{}";
695	
696	        // B1 step 1: merge fragment into state.json BEFORE the git commit.
697	        if (result.FragmentPath is { } fp && File.Exists(fp))
698	        {
699	            MergeFragmentIntoState(statePath, preMergeState, fp);
700	        }
701	
702	        // B1 step 2: git integration commit (FF or non-FF union).
703	        IntegrationResult integResult = provider.Integrate(handle, integ, ct);
704	
705	        if (integResult == IntegrationResult.FastForward)
706	        {
707	            // FF is free — no re-verify needed. Consume one merge sequence.
708	            long seq = _journal.ReserveMergeSequence();
709	            RecordSucceededSettle(task, result, seq);
710	            return result;
711	        }
712	
713	        if (integResult == IntegrationResult.Conflict)
714	        {
715	            // AI merge worker resolves the conflict (§9.1). If no worker is wired or all
716	            // attempts fail, escalate to needs-human with a full B1 rollback.
717	            bool aiResolved = _aiMergeWorker != null
718	                && await _aiMergeWorker.TryResolveAsync(
719	                    integ.IntegrationWorktreePath,
720	                    handle.SegmentBranchName,
721	                    _plan.PlanDirectory,
722	                    ct).ConfigureAwait(false);
723	
724	            if (!aiResolved)
725	            {
726	                AtomicFile.WriteAllText(statePath, preMergeState);
727	                provider.RollbackMerge(integ, ct);
728	                _journal.RecordSettle(task.Id, JournalTaskStatus.NeedsHuman, null);
729	                return new TaskResult
730	                {
731	                    TaskId = task.Id,
732	                    Outcome = TaskOutcome.NeedsHuman,
733	                    ActionExitCode = result.ActionExitCode,
734	                    Guardrails = result.Guardrails,
735	                    Summary = "merge conflict could not be AI-resolved; needs human"
736	                };
737	            }
738	
739	            // AI merge succeeded: re-verify the merged bytes against the SAME integration
740	            // set as the non-AI-merge union path below (§4.3, v1 contract). Running the FULL
741	            // per-task set here false-fails by construction — it includes per-attempt
742	            // anti-tautology guardrails (tests-fail-on-current-code, which PASS post-merge),
743	            // scaffold-state and state-fragment-present checks (no action fragment exists at a
744	            // union point), and downstream tasks that have not run yet. The B-3 "AI may drop a
745	            // colliding sibling's hunk" concern is covered by the integration-scope union
746	            // guardrails (a well-authored integration/union-verify guardrail catches a dropped
747	            // hunk), the disjoint-scope CHECK, and the terminal integration gate — not by
748	            // re-running the full per-task set (which would be inconsistent with the union path).
749	            IReadOnlyList<GuardrailDefinition> aiIntegGuardrails =
750	                GuardrailScopeFilter.IntegrationSet(_plan.Tasks.SelectMany(t => t.Guardrails));
751	
752	            ReVerifyResult aiReVerify = _reVerifier != null
753	                ? await _reVerifier.ReVerifyAsync(integ.IntegrationWorktreePath, aiIntegGuardrails, ct).ConfigureAwait(false)
754	                : new ReVerifyResult { Passed = true };
755	
756	            if (aiReVerify.Passed)
757	            {
758	                // B2: commit the AI-resolved staged merge with the task trailer BEFORE journaling.
759	                provider.CommitStagedMerge(integ, task.Id, ct);
760	                long seq = _journal.ReserveMergeSequence();
761	                RecordSucceededSettle(task, result, seq);
762	                return result;
763	            }
764	
765	            // Re-verify failed after AI merge: B1 four-effect rollback.
766	            // #188: persist the failing integration guardrails' output + a feedback.md to the task log
767	            // dir BEFORE the rollback discards the merged bytes, so a human has the WHY on disk.
768	            string aiFeedbackPath = PersistUnionReVerifyFailure(task, result, integ, aiReVerify, aiMerge: true);
769	            AtomicFile.WriteAllText(statePath, preMergeState);
770	            provider.RollbackMerge(integ, ct);
771	            _journal.RecordSettle(task.Id, JournalTaskStatus.NeedsHuman, null);
772	            return new TaskResult
773	            {
774	                TaskId = task.Id,
775	                Outcome = TaskOutcome.NeedsHuman,
776	                ActionExitCode = result.ActionExitCode,
777	                Guardrails = result.Guardrails,
778	                Summary = "AI-merge resolution failed integration re-verify; needs human " +
779	                          $"(see {aiFeedbackPath})"
780	            };
781	        }
782	
783	        // Non-FF union: re-verify the merged bytes in the integration worktree.
784	        IReadOnlyList<GuardrailDefinition> integGuardrails =
785	            GuardrailScopeFilter.IntegrationSet(_plan.Tasks.SelectMany(t => t.Guardrails));
786	
787	        ReVerifyResult reVerify = _reVerifier != null
788	            ? await _reVerifier.ReVerifyAsync(integ.IntegrationWorktreePath, integGuardrails, ct).ConfigureAwait(false)
789	            : new ReVerifyResult { Passed = true };
790	
791	        if (reVerify.Passed)
792	        {
793	            // B2 step 2: commit the staged non-FF union with the task trailer BEFORE journaling,
794	            // so the plan branch carries this task's Guardrails-Task: trailer (the FF path commits
795	            // implicitly via the FF move; the non-FF path must commit the staged merge explicitly).
796	            provider.CommitStagedMerge(integ, task.Id, ct);
797	            long seq = _journal.ReserveMergeSequence();
798	            RecordSucceededSettle(task, result, seq);
799	            return result;
800	        }
801	
802	        // #188: persist the failing integration guardrails' output + a feedback.md to the task log dir
803	        // BEFORE the four-effect rollback discards the merged bytes — otherwise the needs-human summary
804	        // points at a feedback.md that was never written and the failing guardrail output is lost.
805	        string feedbackPath = PersistUnionReVerifyFailure(task, result, integ, reVerify, aiMerge: false);
806	
807	        // B1 four-effect rollback:
808	        // 1. Restore state.json (undo fragment merge).
809	        AtomicFile.WriteAllText(statePath, preMergeState);
810	        // 2. Reset integration worktree to pre-merge HEAD.
811	        provider.RollbackMerge(integ, ct);
812	        // 3. Journal NeedsHuman — mergeSequence NOT consumed.
813	        _journal.RecordSettle(task.Id, JournalTaskStatus.NeedsHuman, null);
814	
815	        return new TaskResult
816	        {
817	            TaskId = task.Id,
818	            Outcome = TaskOutcome.NeedsHuman,
819	            ActionExitCode = result.ActionExitCode,
820	            Guardrails = result.Guardrails,
821	            Summary = $"non-FF union re-verify failed; rolled back (B1 four-effect) (see {feedbackPath})"
822	        };
823	    }
824	
825	    /// <summary>
826	    /// Persist a failed union re-verify's evidence to the task log dir (issue #188): one
827	    /// <c>union-reverify-&lt;guardrail&gt;.stdout.log</c> per failing integration guardrail carrying its
828	    /// captured output, plus the <c>feedback.md</c> the needs-human summary points at (which the B1
829	    /// rollback path previously PROMISED but never wrote). Called BEFORE the rollback resets the
830	    /// integration worktree, so the merged-bytes evidence survives the discard. Returns the absolute
831	    /// <c>feedback.md</c> path for the summary. Best-effort: an IO failure here must never mask the
832	    /// underlying re-verify failure, so it degrades to returning the intended path.
833	    /// </summary>
834	    private string PersistUnionReVerifyFailure(
835	        TaskNode task, TaskResult result, IntegrationHandle integ, ReVerifyResult reVerify, bool aiMerge)
836	    {
837	        // The task log dir is the PARENT of this attempt's log dir. Derive it from the attempt's own
838	        // relative logDir (logs/<runId>/<taskId>/attempt-N) — which uses the JOURNAL's runId, the same
839	        // runId the executor writes attempt artifacts under — so the evidence lands beside them. Fall
840	        // back to integ.RunId only if no attempt data threaded through (defensive).
841	        string taskLogDir = result.PendingAttempt?.LogDir is { Length: > 0 } relLogDir
842	            ? Path.GetDirectoryName(Path.Combine(
843	                _plan.PlanDirectory, relLogDir.Replace('/', Path.DirectorySeparatorChar)))!
844	            : Path.Combine(_plan.PlanDirectory, "logs", integ.RunId, task.Id);
845	        string feedbackPath = Path.Combine(taskLogDir, "feedback.md");
846	
847	        try
848	        {
849	            Directory.CreateDirectory(taskLogDir);
850	
851	            var failingNames = new List<string>();
852	            foreach (GuardrailResult failed in reVerify.FailedGuardrails)
853	            {
854	                failingNames.Add(failed.Name);
855	                string safe = SanitizeGuardrailName(failed.Name);
856	                // GuardrailResult.Output is the full captured output on failure (stdout, or stderr when
857	                // stdout was empty); Reason is its first line. Persist both so the evidence is complete.
858	                string body = failed.Output ?? failed.Reason ?? "(no output captured)";
859	                AtomicFile.WriteAllText(
860	                    Path.Combine(taskLogDir, $"union-reverify-{safe}.stdout.log"), body);
861	            }
862	
863	            string mergeKind = aiMerge ? "AI-merge resolution" : "non-FF union merge";
864	            string detail = reVerify.FailedGuardrails.Count == 0
865	                ? "The integration re-verify failed but reported no per-guardrail detail."
866	                : string.Join("\n\n", reVerify.FailedGuardrails.Select(g =>
867	                    $"## {g.Name}\n\n{g.Reason ?? "(no reason)"}\n\n" +
868	                    $"Full output persisted to `union-reverify-{SanitizeGuardrailName(g.Name)}.stdout.log`."));
869	
870	            string feedback =
871	                $"# Task '{task.Id}' — union re-verify failed\n\n" +
872	                $"Task: {task.Description}\n\n" +
873	                $"The {mergeKind} produced bytes that FAILED the integration-guardrail re-verify, so the " +
874	                "harness rolled the merge back (state.json restored, integration worktree reset) and settled " +
875	                "this task `needs-human`. The merged bytes were discarded, but each failing integration " +
876	                "guardrail's output was persisted next to this file:\n\n" +
877	                $"{detail}\n\n" +
878	                "This is typically a MERGE COLLISION (two colliding contributions combined into something " +
879	                "that no longer builds/passes) — inspect the persisted output, fix the offending task(s), " +
880	                "and re-run.\n";
881	            AtomicFile.WriteAllText(feedbackPath, feedback);
882	        }
883	        catch
884	        {
885	            // Best-effort — never let a logging IO failure mask the re-verify failure itself.
886	        }
887	
888	        return feedbackPath;
889	    }
890	
891	    /// <summary>Filename-safe form of a guardrail name for the #188 union-reverify log artifacts.</summary>
892	    private static string SanitizeGuardrailName(string name)
893	    {
894	        Span<char> buffer = stackalloc char[name.Length];
895	        for (int i = 0; i < name.Length; i++)
896	        {
897	            char c = name[i];
898	            buffer[i] = char.IsLetterOrDigit(c) || c is '-' or '_' or '.' ? c : '_';
899	        }
900	
901	        return new string(buffer);
902	    }
903	
904	    /// <summary>
905	    /// Record a worktree-mode SUCCESS settle (issue #196): journal a real
906	    /// <see cref="Journal.AttemptRecord"/> for the just-completed attempt TOGETHER with the reserved
907	    /// <paramref name="mergeSequence"/>, so a succeeded worktree task has a populated <c>Attempts</c>
908	    /// list exactly like a succeeded serial task (SSOT §7). The attempt data was computed by the
909	    /// executor and threaded here on <see cref="TaskResult.PendingAttempt"/>; its stamped
910	    /// <see cref="AttemptOutcome.Succeeded"/> outcome carries the #198 provenance (model + segment
911	    /// worktree + base commit). A result missing its <see cref="TaskResult.PendingAttempt"/> (a
912	    /// fake-provider path that never went through <c>ValidateFragmentForSettle</c>) falls back to the
913	    /// attempt-less <see cref="ISchedulerJournal.RecordSettle"/>, so no path regresses.
914	    /// </summary>
915	    private void RecordSucceededSettle(TaskNode task, TaskResult result, long mergeSequence)
916	    {
917	        if (result.PendingAttempt is not { } pending)
918	        {
919	            _journal.RecordSettle(task.Id, JournalTaskStatus.Succeeded, mergeSequence);
920	            return;
921	        }
922	
923	        var record = new Journal.AttemptRecord
924	        {
925	            Attempt = pending.Attempt,
926	            StartedAt = pending.StartedAt,
927	            EndedAt = DateTimeOffset.UtcNow,
928	            ActionExitCode = pending.ActionExitCode,
929	            Outcome = Journal.AttemptOutcome.Succeeded,
930	            CostUsd = pending.CostUsd,
931	            LogDir = pending.LogDir,
932	            Provenance = pending.Provenance
933	        };
934	        _journal.RecordSettleWithAttempt(task.Id, record, JournalTaskStatus.Succeeded, mergeSequence);
935	    }
936	
937	    /// <summary>
938	    /// Shallow-merge <paramref name="fragmentPath"/> into state.json at <paramref name="statePath"/>.
939	    /// The fragment was already validated (valid JSON object, no foreign keys). Uses atomic write.
940	    /// </summary>
941	    private static void MergeFragmentIntoState(string statePath, string preMergeState, string fragmentPath)
942	    {
943	        var stateObj = (JsonNode.Parse(preMergeState) as JsonObject) ?? new JsonObject();
944	        string rawFrag = File.ReadAllText(fragmentPath);
945	        var fragObj = (JsonNode.Parse(rawFrag) as JsonObject) ?? new JsonObject();
946	
947	        foreach (var (key, value) in fragObj)
948	        {
949	            stateObj[key] = value?.DeepClone();
950	        }
951	
952	        AtomicFile.WriteAllText(statePath, stateObj.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));
953	    }
954	
955	    /// <summary>
956	    /// Convert an all-green report into a needs-human one when the terminal integration gate
957	    /// (§3.3) failed on the final plan-branch HEAD. The failure is attributed to the
958	    /// <c>integrationGate:true</c> sink task (or, absent one, the last task in plan order) so the
959	    /// run is not certified and mergeOnSuccess is refused.
960	    /// <para>
961	    /// #175 attribution: a terminal-gate (typically whole-repo build/test) failure on the merged HEAD
962	    /// is frequently a MERGE COLLISION — two tasks with OVERLAPPING <c>writeScope</c> on a shared file
963	    /// both wrote new content there and git's 3-way merge silently kept both (a semantic duplicate, no
964	    /// textual conflict marker). The harness cannot generically detect the duplicate (that is the build
965	    /// guardrail's job), but it CAN name the suspects: the diagnosis lists every overlapping-writeScope
966	    /// task pair and the shared path so a human immediately sees "this looks like a merge collision
967	    /// between task A and task B on &lt;file&gt;" instead of a bare build error. Advisory and robust —
968	    /// based PURELY on the writeScope-overlap structure (never the error text / a CS-code), and adds
969	    /// nothing when no writeScopes overlap.
970	    /// </para>
971	    /// </summary>
972	    private static RunReport WithTerminalGateFailure(
973	        PlanDefinition plan, RunReport report, ReVerifyResult gate)
974	    {
975	        string gateTaskId =
976	            plan.Tasks.LastOrDefault(t => t.IntegrationGate)?.Id
977	            ?? plan.Tasks[^1].Id;
978	
979	        string failed = string.Join(", ", gate.FailedGuardrails.Select(g => g.Name));
980	        string summary = $"terminal integration gate failed on final HEAD: {failed}";
981	
982	        string? collisionHint = WriteScope.OverlappingWriteScopeHint(plan);
983	        if (collisionHint is not null)
984	        {
985	            summary += $". {collisionHint}";
986	        }
987	
988	        var rewritten = report.Tasks.Select(t => t.TaskId == gateTaskId
989	            ? t with
990	            {
991	                Outcome = TaskOutcome.NeedsHuman,
992	                Guardrails = gate.FailedGuardrails,
993	                Summary = summary
994	            }
995	            : t).ToList();
996	
997	        return report with { Tasks = rewritten };
998	    }
999	
1000	    private static RunReport BuildReport(
1001	        PlanDefinition plan,
1002	        IReadOnlyDictionary<string, TaskResult> settled,
1003	        bool cancelled)
1004	    {
1005	        var results = new List<TaskResult>(plan.Tasks.Count);
1006	        foreach (TaskNode task in plan.Tasks)
1007	        {
1008	            results.Add(settled.TryGetValue(task.Id, out TaskResult? result)
1009	                ? result
1010	                : new TaskResult
1011	                {
1012	                    TaskId = task.Id,
1013	                    Outcome = TaskOutcome.Cancelled,
1014	                    Summary = "not started (run cancelled)"
1015	                });
1016	        }
1017	
1018	        return new RunReport { Tasks = results, Cancelled = cancelled };
1019	    }
1020	
1021	    /// <summary>
1022	    /// Per-task channel item pairing a task with its assigned worktree handle. When
1023	    /// <see cref="Fork"/> is non-null the handle is a placeholder and the worker materializes the
1024	    /// real fork worktree off-gate at dequeue (M1 §B); otherwise <see cref="Handle"/> is the final
1025	    /// assigned segment/reused directory.
1026	    /// </summary>
1027	    private readonly record struct TaskEnvelope(TaskNode Task, WorktreeHandle Handle, ForkRequest? Fork = null);
1028	
1029	    /// <summary>
1030	    /// A deferred fork-the-rest request (M1 §B): the producer's RECORDED commit sha to fork off
1031	    /// (W-2 — never a live rev-parse of the inheritor-advanced segment branch). Materialized by the
1032	    /// worker via <see cref="IWorktreeProvider.ForkFromTip"/> before the task's action runs.
1033	    /// </summary>
1034	    private readonly record struct ForkRequest(string ProducerRecordedSha);
1035	
1036	    /// <summary>Mutable shared state of one run, guarded by the scheduler's gate.</summary>
1037	    private sealed class RunContext(
1038	        DependencyGraph graph,
1039	        IReadOnlyDictionary<string, TaskNode> byId,
1040	        Dictionary<string, TaskResult> settled,
1041	        Dictionary<string, int> pendingDeps,
1042	        Channel<TaskEnvelope> channel,
1043	        int remaining,
1044	        Dictionary<string, WorktreeHandle> handles,
1045	        Dictionary<string, string> directoryOwner,
1046	        IntegrationHandle? integ)
1047	    {
1048	        public DependencyGraph Graph { get; } = graph;
1049	        public IReadOnlyDictionary<string, TaskNode> ById { get; } = byId;
1050	        public Dictionary<string, TaskResult> Settled { get; } = settled;
1051	        public Dictionary<string, int> PendingDeps { get; } = pendingDeps;
1052	        public Channel<TaskEnvelope> Channel { get; } = channel;
1053	        public int Remaining { get; set; } = remaining;
1054	        public Dictionary<string, WorktreeHandle> Handles { get; } = handles;
1055	
1056	        /// <summary>
1057	        /// plan 08 topology-wiring M0 bookkeeping: worktree path → current owning task id. Written
1058	        /// under <see cref="_gate"/> only (CreateSegment/ForkFromTip set it; ReuseSegment transfers
1059	        /// ownership to the inheritor; Discard removes the entry). The single source of truth for
1060	        /// "is this directory free to Discard / reuse?".
1061	        /// </summary>
1062	        public Dictionary<string, string> DirectoryOwner { get; } = directoryOwner;
1063	        public IntegrationHandle? Integ { get; } = integ;
1064	    }
1065	}
