            if (Interlocked.Increment(ref _arrivedCount) == _expectedCount)
                _allArrived.TrySetResult();

            // Block until ALL tasks are simultaneously in flight — this IS the overlap proof.
            await _allArrived.Task.WaitAsync(ct);

